"""Generate time-of-use energy bills from the supplied input files."""

from __future__ import annotations

import argparse
import csv
import json
import os
import re
import tempfile
from collections import defaultdict
from dataclasses import dataclass
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from typing import Iterable, Mapping, Sequence
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError


CENT = Decimal("0.01")
FOUR_PLACES = Decimal("0.0001")
THREE_PLACES = Decimal("0.001")


@dataclass(frozen=True)
class Customer:
    customer_id: str
    timezone: ZoneInfo
    tax_rate: Decimal


@dataclass(frozen=True)
class Rate:
    band: str
    effective_from: datetime
    effective_to: datetime
    price_per_kwh: Decimal
    rate_id: str


@dataclass(frozen=True)
class Demand:
    price_per_kw: Decimal
    qualifying_bands: frozenset[str]
    rate_id: str


@dataclass(frozen=True)
class Tariff:
    schedules: Mapping[str, tuple[tuple[int, int, str], ...]]
    rates_by_band: Mapping[str, tuple[Rate, ...]]
    demand: Demand


@dataclass
class EnergyGroup:
    count: int = 0
    kwh: Decimal = Decimal(0)
    price_per_kwh: Decimal = Decimal(0)


def _decimal(value: object, field: str) -> Decimal:
    try:
        result = Decimal(str(value))
    except Exception as exc:
        raise ValueError(f"invalid decimal for {field}: {value!r}") from exc
    if not result.is_finite():
        raise ValueError(f"non-finite decimal for {field}: {value!r}")
    return result


def _wall_datetime(value: object, field: str) -> datetime:
    try:
        result = datetime.fromisoformat(str(value))
    except ValueError as exc:
        raise ValueError(f"invalid local datetime for {field}: {value!r}") from exc
    if result.tzinfo is not None:
        raise ValueError(f"{field} must be a timezone-free local wall time")
    return result


def _boundary_minutes(value: object, *, is_end: bool) -> int:
    text = str(value)
    if text == "24:00":
        if not is_end:
            raise ValueError("24:00 is only valid as a schedule end boundary")
        return 24 * 60
    try:
        parsed = datetime.strptime(text, "%H:%M")
    except ValueError as exc:
        raise ValueError(f"invalid schedule boundary: {text!r}") from exc
    return parsed.hour * 60 + parsed.minute


def load_customers(path: Path) -> dict[str, Customer]:
    customers: dict[str, Customer] = {}
    with path.open("r", encoding="utf-8", newline="") as stream:
        reader = csv.DictReader(stream)
        required = {"customer_id", "timezone", "tax_rate"}
        if reader.fieldnames is None or not required.issubset(reader.fieldnames):
            raise ValueError(f"{path} must contain columns {sorted(required)}")
        for line, row in enumerate(reader, 2):
            customer_id = row["customer_id"]
            if not customer_id or customer_id in customers:
                raise ValueError(f"invalid or duplicate customer_id on {path}:{line}")
            try:
                timezone = ZoneInfo(row["timezone"])
            except ZoneInfoNotFoundError as exc:
                raise ValueError(f"unknown timezone on {path}:{line}: {row['timezone']!r}") from exc
            customers[customer_id] = Customer(
                customer_id, timezone, _decimal(row["tax_rate"], "tax_rate")
            )
    return customers


def load_holidays(path: Path) -> frozenset[date]:
    with path.open("r", encoding="utf-8") as stream:
        data = json.load(stream)
    try:
        return frozenset(date.fromisoformat(value) for value in data["dates"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(f"invalid holidays file: {path}") from exc


def load_tariff(path: Path) -> Tariff:
    with path.open("r", encoding="utf-8") as stream:
        data = json.load(stream)
    if data.get("effective_time_basis") != "customer_local":
        raise ValueError("tariff effective_time_basis must be 'customer_local'")

    schedules: dict[str, tuple[tuple[int, int, str], ...]] = {}
    try:
        raw_schedules = data["day_schedules"]
        for day_type in ("weekday", "weekend", "holiday"):
            bands = []
            for entry in raw_schedules[day_type]:
                start = _boundary_minutes(entry["start"], is_end=False)
                end = _boundary_minutes(entry["end"], is_end=True)
                if start >= end:
                    raise ValueError(f"invalid {day_type} schedule interval")
                bands.append((start, end, str(entry["band"])))
            schedules[day_type] = tuple(bands)
    except (KeyError, TypeError) as exc:
        raise ValueError(f"invalid day schedules in {path}") from exc

    rates: dict[str, list[Rate]] = defaultdict(list)
    try:
        for entry in data["energy_rates"]:
            rate = Rate(
                band=str(entry["band"]),
                effective_from=_wall_datetime(entry["effective_from"], "effective_from"),
                effective_to=_wall_datetime(entry["effective_to"], "effective_to"),
                price_per_kwh=_decimal(entry["price_per_kwh"], "price_per_kwh"),
                rate_id=str(entry["rate_id"]),
            )
            if rate.effective_from >= rate.effective_to:
                raise ValueError(f"invalid effective period for rate {rate.rate_id!r}")
            rates[rate.band].append(rate)
        raw_demand = data["demand"]
        demand = Demand(
            price_per_kw=_decimal(raw_demand["price_per_kw"], "price_per_kw"),
            qualifying_bands=frozenset(map(str, raw_demand["qualifying_bands"])),
            rate_id=str(raw_demand["rate_id"]),
        )
    except (KeyError, TypeError) as exc:
        raise ValueError(f"invalid rates in {path}") from exc
    return Tariff(schedules, {band: tuple(items) for band, items in rates.items()}, demand)


def _band_for(local: datetime, tariff: Tariff, holidays: frozenset[date]) -> str:
    if local.date() in holidays:
        day_type = "holiday"
    elif local.weekday() >= 5:
        day_type = "weekend"
    else:
        day_type = "weekday"
    minute = local.hour * 60 + local.minute
    matches = [band for start, end, band in tariff.schedules[day_type] if start <= minute < end]
    if len(matches) != 1:
        raise ValueError(f"local time {local.isoformat()} matches {len(matches)} schedule bands")
    return matches[0]


def _rate_for(local_wall: datetime, band: str, tariff: Tariff) -> Rate:
    matches = [
        rate
        for rate in tariff.rates_by_band.get(band, ())
        if rate.effective_from <= local_wall < rate.effective_to
    ]
    if len(matches) != 1:
        raise ValueError(
            f"local time {local_wall.isoformat()} in band {band!r} matches {len(matches)} rates"
        )
    return matches[0]


def _money(value: Decimal) -> Decimal:
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def _format(value: Decimal, quantum: Decimal) -> str:
    return format(value.quantize(quantum, rounding=ROUND_HALF_UP), "f")


def calculate(
    input_dir: Path, period: str
) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    if re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", period) is None:
        raise ValueError(f"period must be YYYY-MM: {period!r}")
    try:
        period_start = datetime.strptime(period, "%Y-%m")
    except ValueError as exc:
        raise ValueError(f"period must be YYYY-MM: {period!r}") from exc

    customers = load_customers(input_dir / "customers.csv")
    holidays = load_holidays(input_dir / "holidays.json")
    tariff = load_tariff(input_dir / "tariffs.json")
    groups: dict[tuple[str, str, str], EnergyGroup] = {}
    demand_max: dict[str, Decimal] = {}

    readings_path = input_dir / "readings.csv"
    with readings_path.open("r", encoding="utf-8", newline="") as stream:
        reader = csv.DictReader(stream)
        required = {"customer_id", "interval_start", "kwh", "kw"}
        if reader.fieldnames is None or not required.issubset(reader.fieldnames):
            raise ValueError(f"{readings_path} must contain columns {sorted(required)}")
        for line, row in enumerate(reader, 2):
            customer = customers.get(row["customer_id"])
            if customer is None:
                raise ValueError(f"unknown customer_id on {readings_path}:{line}")
            try:
                instant = datetime.fromisoformat(row["interval_start"])
            except ValueError as exc:
                raise ValueError(f"invalid interval_start on {readings_path}:{line}") from exc
            if instant.tzinfo is None or instant.utcoffset() is None:
                raise ValueError(f"interval_start lacks UTC offset on {readings_path}:{line}")
            local = instant.astimezone(customer.timezone)
            if (local.year, local.month) != (period_start.year, period_start.month):
                continue
            local_wall = local.replace(tzinfo=None)
            band = _band_for(local, tariff, holidays)
            rate = _rate_for(local_wall, band, tariff)
            kwh = _decimal(row["kwh"], "kwh")
            kw = _decimal(row["kw"], "kw")

            key = (customer.customer_id, band, rate.rate_id)
            group = groups.setdefault(key, EnergyGroup(price_per_kwh=rate.price_per_kwh))
            if group.price_per_kwh != rate.price_per_kwh:
                raise ValueError(f"rate_id {rate.rate_id!r} has conflicting prices")
            group.count += 1
            group.kwh += kwh
            if band in tariff.demand.qualifying_bands and kwh >= 0:
                previous = demand_max.get(customer.customer_id)
                if previous is None or kw > previous:
                    demand_max[customer.customer_id] = kw

    detail_rows: list[dict[str, str]] = []
    energy_totals: dict[str, Decimal] = defaultdict(Decimal)
    for (customer_id, band, rate_id), group in sorted(groups.items()):
        charge = _money(group.kwh * group.price_per_kwh)
        energy_totals[customer_id] += charge
        detail_rows.append(
            {
                "customer_id": customer_id,
                "period": period,
                "band": band,
                "rate_id": rate_id,
                "interval_count": str(group.count),
                "kwh": _format(group.kwh, FOUR_PLACES),
                "energy_charge": _format(charge, CENT),
            }
        )

    bill_rows: list[dict[str, str]] = []
    for customer_id in sorted(customers):
        customer = customers[customer_id]
        energy_charge = energy_totals[customer_id]
        demand_kw = demand_max.get(customer_id, Decimal(0))
        demand_charge = _money(demand_kw * tariff.demand.price_per_kw)
        tax_charge = _money((energy_charge + demand_charge) * customer.tax_rate)
        total = energy_charge + demand_charge + tax_charge
        bill_rows.append(
            {
                "customer_id": customer_id,
                "period": period,
                "energy_charge": _format(energy_charge, CENT),
                "demand_rate_id": tariff.demand.rate_id,
                "demand_kw": _format(demand_kw, THREE_PLACES),
                "demand_charge": _format(demand_charge, CENT),
                "tax_rate": _format(customer.tax_rate, FOUR_PLACES),
                "tax_charge": _format(tax_charge, CENT),
                "total": _format(total, CENT),
            }
        )
    return bill_rows, detail_rows


def _write_csv(path: Path, fieldnames: Sequence[str], rows: Iterable[Mapping[str, str]]) -> None:
    """Atomically replace a deterministic UTF-8/LF CSV file."""
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="") as stream:
            writer = csv.DictWriter(stream, fieldnames=fieldnames, lineterminator="\n")
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary_name, path)
    except BaseException:
        try:
            os.unlink(temporary_name)
        except FileNotFoundError:
            pass
        raise


def run(input_dir: Path, period: str, output_dir: Path) -> None:
    bills, details = calculate(input_dir, period)
    output_dir.mkdir(parents=True, exist_ok=True)
    _write_csv(
        output_dir / "bills.csv",
        (
            "customer_id", "period", "energy_charge", "demand_rate_id", "demand_kw",
            "demand_charge", "tax_rate", "tax_charge", "total",
        ),
        bills,
    )
    _write_csv(
        output_dir / "bill_detail.csv",
        ("customer_id", "period", "band", "rate_id", "interval_count", "kwh", "energy_charge"),
        details,
    )


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("inputs", type=Path, help="directory containing billing input files")
    parser.add_argument("--period", required=True, help="customer-local billing month (YYYY-MM)")
    parser.add_argument("--output", required=True, type=Path, help="output directory")
    args = parser.parse_args(argv)
    try:
        run(args.inputs, args.period, args.output)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        parser.exit(1, f"energy_bill: {exc}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
